var _H  = 'https://maihaolian.com';
var _UA = 'Mozilla/5.0 (compatible; Baiduspider/2.0; +http://www.baidu.com/search/spider.html)';

/* ---------- 统一请求头 ---------- */
function _hdr(ref) {
    return {
        headers: {
            'User-Agent': _UA,
            'Referer': ref ? ref : (_H + '/'),
            'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
            'Accept-Language': 'zh-CN,zh;q=0.9'
        }
    };
}

/* ---------- 盾页判定 ---------- */
function _isShield(h) {
    if (!h || h.length < 800) { return true; }
    if (h.indexOf('系统安全验证') >= 0) { return true; }
    if (h.indexOf('mx-mac_msg_jump') >= 0) { return true; }
    return false;
}

/* ---------- 绝对化 ---------- */
function _full(u) {
    if (!u) { return ''; }
    u = String(u);
    if (u.indexOf('http') === 0) { return u; }
    if (u.indexOf('//') === 0) { return 'https:' + u; }
    return _H + '/' + u.replace(/^\.?\//, '');
}

/* ---------- 带 UA 抓取（重试 3 次） ---------- */
function _fetch(u, ref) {
    var url = _full(u);
    var html = '';
    var i;
    for (i = 0; i < 3; i++) {
        try {
            html = String(fetch(url + '#autoCache#', _hdr(ref)) || '');
        } catch (e) {
            html = '';
        }
        if (!_isShield(html)) { return html; }
    }
    return html;
}

    /* ---------- 图片（加 Referer 防盗链；空图直接返回空串） ---------- */
    function _img(u) {
        if (!u) { return ''; }
        return _full(u) + '@Referer=' + _H + '/';
    }

/* ---------- 随机色 ---------- */
function _color() {
    return '#' + ('00000' + (Math.random() * 0x1000000 << 0).toString(16)).substr(-6);
}

/* ---------- 去标签 + 实体 ---------- */
function _txt(s) {
    if (!s) { return ''; }
    return String(s)
        .replace(/<[^>]*>/g, '')
        .replace(/&nbsp;/g, ' ')
        .replace(/&amp;/g, '&')
        .replace(/&quot;/g, '"')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&#\d+;/g, '')
        .replace(/^\s+|\s+$/g, '');
}

/* ============================================================
   分类列表解析（.public-list-box.public-pic-b）
   ============================================================ */
function _parseList(html) {
    var d = [];
    var list = pdfa(html, 'body&&.public-list-box');
    var i;
    for (i = 0; i < list.length; i++) {
        var it  = list[i];
        var href  = pd(it, '.public-list-exp&&href');
        var title = pdfh(it, '.public-list-exp&&title');
        if (!title) { title = _txt(pdfh(it, '.public-list-button&&a&&Text')); }
        var note = _txt(pdfh(it, '.public-list-prb&&Text'));
        var sub  = _txt(pdfh(it, '.public-list-subtitle&&Text'));
        var img  = pd(it, 'img&&data-src');
        if (!img) { img = pd(it, 'img&&src'); }
        if (!href) { continue; }
        d.push({
            title: title,
            desc: note || sub,
            img: _img(img),
            url: _full(href),
            col_type: 'movie_3'
        });
    }
    return d;
}

/* ============================================================
   搜索列表解析（.public-list-box.search-box，结构不同！）
   ============================================================ */
function _parseSearch(html) {
    var d = [];
    var list = pdfa(html, 'body&&.public-list-box');
    var i;
    for (i = 0; i < list.length; i++) {
        var it = list[i];
        var aEls = pdfa(it, '.thumb-txt&&a');
        var title = '';
        var href  = '';
        if (aEls.length > 0) {
            title = _txt(pdfh(aEls[0], 'a&&Text'));
            href  = pd(aEls[0], 'a&&href');
        }
        if (!title) {
            title = pdfh(it, '.public-list-exp&&title');
            href  = pd(it, '.public-list-exp&&href');
        }
        if (!href) { continue; }
        var img  = pd(it, 'img&&data-src');
        if (!img) { img = pd(it, 'img&&src'); }
        var meta = _txt(pdfh(it, '.thumb-else&&Text'));
        var note = _txt(pdfh(it, '.public-list-prb&&Text'));
        d.push({
            title: title,
            desc: note ? (note + ' ' + meta) : meta,
            img: _img(img),
            url: _full(href),
            col_type: 'movie_3'
        });
    }
    return d;
}

